import{_ as s,l as i,o as e,c,v as t,p as l,x as r,d as n,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"原子操作的缓存实现","description":"","frontmatter":{"title":"原子操作的缓存实现","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/atomic-cache-impl.md","filePath":"cs/atomic-cache-impl.md","lastUpdated":1789023840000}'),p={name:"cs/atomic-cache-impl.md"};function E(A,a,m,_,B,f){const o=i("Mermaid");return e(),c("div",null,[a[1]||(a[1]=t('<h1 id="原子操作的缓存实现" tabindex="-1">原子操作的缓存实现 <a class="header-anchor" href="#原子操作的缓存实现" aria-label="Permalink to &quot;原子操作的缓存实现&quot;">​</a></h1><div class="epigraph"><p>CAS 与 fetch-and-add 在程序员看来是一条指令；在 cache 里它们是「拿到 M，在独占期间完成读改写，期间不让出该行」。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；McKenney 对 RMW 与缓存的论述 整理</footer></div><p><a href="/cs/false-sharing">上一课</a> 说明行上的争用极贵。真共享时还需要原子：计数器、锁字、<a href="/cs/lr-sc-cas">LR/SC 与 CAS</a> 在 ISA 对照里已经出现。本课不重讲伪共享填充。缺口是<strong>微结构：原子 RMW 如何挂在 MESI/MOESI 上，以及锁住 cache 行期间发生什么。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通 <code>add</code> 的 load 与 store 之间可以被他核的写插入。<a href="/cs/lsq-disambiguation">LSQ</a> 只保证本核。原子要求中间态对外不可见。缺口不是再加一个目录态，而是<strong>先升级到 M（或等价独占），在 L1 里完成 RMW，期间对该行的窥探延迟应答或重试。</strong></p><p><span class="marginnote">x86 <code>lock</code> 前缀历史上锁总线；当代是 cache lock：只锁该行。LR/SC：SC 时若行被作废则失败，不必全程占 M。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行原子：发出 Read-for-Ownership，等目录/窥探把 sharer 作废，行进 M。在 L1 对对齐地址做 ALU。提交前若被探询，要么延迟探询到 RMW 完成，要么放弃（SC 失败）。然后该行保持 M，或按协议共享。</p>',8)),(e(),l(h,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ATO%5B%22%E5%8E%9F%E5%AD%90%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20RFO%5B%22%E6%B1%82%20M%20%2F%20%E7%8B%AC%E5%8D%A0%22%5D%0A%20%20RFO%20--%3E%20RMW%5B%22L1%20%E5%86%85%E8%AF%BB%E6%94%B9%E5%86%99%22%5D%0A%20%20RMW%20--%3E%20HOLD%5B%22%E6%9C%9F%E9%97%B4%E5%BB%B6%E8%BF%9F%E6%88%96%E6%8B%92%E7%BB%9D%E6%8E%A2%E8%AF%A2%22%5D%0A%20%20HOLD%20--%3E%20DONE%5B%22%E6%8F%90%E4%BA%A4%EF%BC%8C%E8%A1%8C%E4%BB%8D%20M%20%E6%88%96%E6%8C%89%E6%A8%A1%E5%9E%8B%E9%99%8D%E7%BA%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对齐：跨行原子要么禁止，要么锁两行——实现极痛，ISA 常要求自然对齐。争用：多个核打同一锁字 = 真共享 + 伪共享式颠簸，<a href="/cs/cache-partition-qos">分区</a> 救不了。指数退避在软件；硬件只保证这一次 RMW 的原子性。</p><p>与 <a href="/cs/retire-precise-exception">退休</a>：原子通常要在 ROB 头附近执行或至少提交时行仍独占，否则精确异常难定义。这降低 MLP：原子像一个小栅栏。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 ISA 的原子清单写全。下一课 acquire/release 把「这一次 RMW」推广到「周围普通 load/store 能否重排」。事务内存则把多行原子合成一块，再下一课。</p><p>后课默认：原子 = 独占行上的 RMW。单地址原子还不够表达「解锁之前的写要对获取锁的人可见」——那是 acquire/release。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原子 RMW 先拿 M，在 L1 完成，探询被推迟或 SC 失败。</li><li>跨行与高争用是性能悬崖。</li><li>把周围访存的顺序钉到释放/获取语义，是下一课。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；McKenney。</li></ul>',8))])}const C=s(p,[["render",E]]);export{M as __pageData,C as default};
